function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // snake body
  ctx.beginPath();
  ctx.moveTo(W / 2 + Math.sin(t) * 50, H / 2);
  for (let i = 0; i < 10; i++) {
    ctx.lineTo(W / 2 + Math.sin(t + i) * 50, H / 2 + i * 20);
  }
  ctx.stroke();

  // shedding skin
  ctx.globalAlpha = 0.5;
  ctx.beginPath();
  ctx.moveTo(W / 2 + Math.sin(t + Math.PI) * 50, H / 2);
  for (let i = 0; i < 10; i++) {
    ctx.lineTo(W / 2 + Math.sin(t + Math.PI + i) * 50, H / 2 + i * 20);
  }
  ctx.stroke();
  ctx.globalAlpha = 1;

  // head
  ctx.beginPath();
  ctx.arc(W / 2 + Math.sin(t) * 50, H / 2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // eyes
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W / 2 + Math.sin(t) * 50 - 5, H / 2 - 5, 2, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W / 2 + Math.sin(t) * 50 + 5, H / 2 - 5, 2, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
